const body = $('Webhook Invoice Upload').first().json.body || {};
if (!body.project_id) {
  const e = { valid: false, error: 'project_id obligatorio' };
  return [{ json: e }];
}
if (!body.photo_url || typeof body.photo_url !== 'string' || !body.photo_url.startsWith('http')) {
  const e = { valid: false, error: 'photo_url http(s) obligatorio' };
  return [{ json: e }];
}
const out = {
  valid: true,
  project_id: body.project_id,
  photo_url: body.photo_url,
  trade_type_hint: body.trade_type || null,
  notes: (body.notes || '').toString().slice(0, 1000),
  started_at: Date.now()
};
return [{ json: out }];

const input = $input.first().json;
const systemPrompt = 'Eres un experto en OCR de facturas espanolas. Extraes datos estructurados con precision. Responde SOLO con JSON valido sin markdown.';
const userText = [
  'Extrae los datos de esta factura espanola.',
  '',
  input.trade_type_hint ? 'Pista de gremio (puede ayudar a categorizar): ' + input.trade_type_hint : '',
  input.notes ? 'Notas del arquitecto: ' + input.notes : '',
  '',
  'Devuelve JSON exacto:',
  '{',
  '  "supplier_name": "razon social del proveedor",',
  '  "supplier_nif": "NIF/CIF si visible",',
  '  "invoice_number": "numero de factura",',
  '  "invoice_date": "YYYY-MM-DD",',
  '  "base_amount": 0.00,',
  '  "vat_amount": 0.00,',
  '  "total_amount": 0.00,',
  '  "vat_rate": 21.00,',
  '  "category": "materiales|mano_obra|servicios|otros",',
  '  "trade_type": "albanileria|fontaneria|electricidad|carpinteria|pintura|climatizacion|sanitarios|otros",',
  '  "description": "resumen 1-2 frases del concepto",',
  '  "line_items": [{"concepto":"...", "cantidad":"...", "precio_unit":0, "importe":0}],',
  '  "confidence": "low|medium|high"',
  '}',
  '',
  'Si un dato no es legible: usa null. Marca confidence: "low" si la imagen tiene mala calidad o no es factura.'
].filter(Boolean).join('\n');

const payload = {
  model: 'gpt-4o',
  max_tokens: 1500,
  temperature: 0.1,
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: [
      { type: 'text', text: userText },
      { type: 'image_url', image_url: { url: input.photo_url, detail: 'high' } }
    ]}
  ]
};
return [{ json: { ...input, payload: payload } }];

const llm = $input.first().json;
const built = $('Build OCR Prompt').first().json;
const content = llm.choices && llm.choices[0] && llm.choices[0].message && llm.choices[0].message.content || '';
const usage = llm.usage || {};
const tokensIn = usage.prompt_tokens || 0;
const tokensOut = usage.completion_tokens || 0;
const cost = (tokensIn / 1000) * 0.0025 + (tokensOut / 1000) * 0.01;

let parsed = {};
try {
  const m = content.match(/\{[\s\S]*\}/);
  if (m) parsed = JSON.parse(m[0]);
} catch(e) {
  parsed = { confidence: 'low', description: 'Error parsing: ' + e.message };
}

const summary = (parsed.supplier_name || '?') + ' #' + (parsed.invoice_number || '?') + ' - ' + (parsed.total_amount || 0) + 'eur (' + (parsed.invoice_date || '?') + ')';

const out = {
  project_id: built.project_id,
  photo_url: built.photo_url,
  supplier_name: parsed.supplier_name || null,
  supplier_nif: parsed.supplier_nif || null,
  invoice_number: parsed.invoice_number || null,
  invoice_date: parsed.invoice_date || null,
  base_amount: typeof parsed.base_amount === 'number' ? parsed.base_amount : null,
  vat_amount: typeof parsed.vat_amount === 'number' ? parsed.vat_amount : null,
  total_amount: typeof parsed.total_amount === 'number' ? parsed.total_amount : null,
  vat_rate: typeof parsed.vat_rate === 'number' ? parsed.vat_rate : null,
  category: parsed.category || null,
  trade_type: parsed.trade_type || built.trade_type_hint,
  description: parsed.description || null,
  ocr_summary: summary,
  ocr_raw: parsed,
  ocr_confidence: parsed.confidence || 'low',
  llm_model: llm.model || 'gpt-4o',
  llm_tokens_in: tokensIn,
  llm_tokens_out: tokensOut,
  llm_cost: Math.round(cost * 100000) / 100000,
  notes: built.notes || null
};
return [{ json: out }];

const err = $input.first().json;
const built = $('Build OCR Prompt').first().json;
const msg = (err && (err.message || (err.error && err.error.message))) || 'OCR error';
return [{ json: { project_id: built.project_id, photo_url: built.photo_url, error: msg } }];

const inv = $input.first().json;
const built = $('Build OCR Prompt').first().json;
const N8N = 'https://n8n-n8n.zzeluw.easypanel.host';
const tok = encodeURIComponent(inv.webhook_token || '');
const id = inv.id;
const approveUrl = N8N + '/webhook/invoice-decision?id=' + id + '&token=' + tok + '&decision=approved';
const disputeUrl = N8N + '/webhook/invoice-decision?id=' + id + '&token=' + tok + '&decision=disputed';
const rejectUrl = N8N + '/webhook/invoice-decision?id=' + id + '&token=' + tok + '&decision=rejected';
const total = inv.total_amount !== null && inv.total_amount !== undefined ? Number(inv.total_amount).toLocaleString('es-ES') + ' EUR' : '?';
const confColor = { high: '#10b981', medium: '#f59e0b', low: '#dc2626' }[inv.ocr_confidence] || '#6b7280';
const html = '<div style="font-family:Arial,sans-serif;max-width:600px;margin:0 auto">' +
  '<h2 style="color:#2c3e50">Factura recibida — revisión requerida</h2>' +
  '<table style="width:100%;border-collapse:collapse;font-size:13px">' +
  '<tr><td style="padding:6px 8px;background:#f3f4f6;font-weight:bold;width:140px">Proveedor</td><td style="padding:6px 8px">' + (inv.supplier_name || '?') + '</td></tr>' +
  '<tr><td style="padding:6px 8px;background:#f3f4f6;font-weight:bold">Número</td><td style="padding:6px 8px">' + (inv.invoice_number || '?') + '</td></tr>' +
  '<tr><td style="padding:6px 8px;background:#f3f4f6;font-weight:bold">Fecha</td><td style="padding:6px 8px">' + (inv.invoice_date || '?') + '</td></tr>' +
  '<tr><td style="padding:6px 8px;background:#f3f4f6;font-weight:bold">Base imponible</td><td style="padding:6px 8px">' + (inv.base_amount !== null ? Number(inv.base_amount).toLocaleString('es-ES') + ' EUR' : '?') + '</td></tr>' +
  '<tr><td style="padding:6px 8px;background:#f3f4f6;font-weight:bold">IVA</td><td style="padding:6px 8px">' + (inv.vat_rate || '?') + '% (' + (inv.vat_amount !== null ? Number(inv.vat_amount).toLocaleString('es-ES') + ' EUR' : '?') + ')</td></tr>' +
  '<tr><td style="padding:6px 8px;background:#f3f4f6;font-weight:bold">Total</td><td style="padding:6px 8px;font-size:16px;font-weight:bold;color:#2563eb">' + total + '</td></tr>' +
  '<tr><td style="padding:6px 8px;background:#f3f4f6;font-weight:bold">Categoría</td><td style="padding:6px 8px">' + (inv.category || '?') + ' / ' + (inv.trade_type || '?') + '</td></tr>' +
  '<tr><td style="padding:6px 8px;background:#f3f4f6;font-weight:bold">Confianza OCR</td><td style="padding:6px 8px"><span style="background:' + confColor + ';color:white;padding:2px 8px;border-radius:3px">' + (inv.ocr_confidence || '?').toUpperCase() + '</span></td></tr>' +
  '</table>' +
  '<p><a href="' + built.photo_url + '">Ver factura original</a></p>' +
  '<div style="margin:32px 0;text-align:center">' +
  '<a href="' + approveUrl + '" style="background:#10b981;color:white;padding:12px 24px;text-decoration:none;border-radius:4px;font-size:15px;margin:0 6px">✓ Aprobar</a>' +
  '<a href="' + disputeUrl + '" style="background:#f59e0b;color:white;padding:12px 24px;text-decoration:none;border-radius:4px;font-size:15px;margin:0 6px">⚠ Disputar</a>' +
  '<a href="' + rejectUrl + '" style="background:#dc2626;color:white;padding:12px 24px;text-decoration:none;border-radius:4px;font-size:15px;margin:0 6px">✗ Rechazar</a>' +
  '</div>' +
  '<p style="font-size:11px;color:#6b7280">Invoice ID: ' + id + '</p>' +
  '</div>';
return [{ json: { html: html, supplier: inv.supplier_name || '?', total: total, invoice_id: id, status: inv.status, ocr_confidence: inv.ocr_confidence } }];
